/**
 * Guard rails for publishing `@shopwell-ag/entity-schema-types` from GitHub Actions.
 *
 * The package is generated by `npm run generate-entity-schema-package` in the Administration and
 * takes its version mechanically from the release tag (`v6.7.15.0` → `7.15.0`). Two things can be
 * wrong while every command involved still exits `0`, which is why neither check lives in a `run:`
 * block of the workflow:
 *
 *  - the tag may be one the generator cannot turn into a valid semver. The generator rewrites with
 *    `replace('v6.', '')`, so a tag it does not match is published unchanged — `trunk` becomes the
 *    version `trunk`.
 *  - the generated folder may be missing files npm would then silently not publish, or carry a
 *    `repository` that npm's trusted publishing rejects against the workflow's own repository.
 *
 * `derive` refuses the first before generation, `verify` refuses the second after it. The generator
 * exiting successfully is not evidence that it wrote a publishable package.
 *
 * Usage:
 *   entity-schema-package.ts derive   Reads the release tag, writes `version` and
 *                                     `already_published` to `$GITHUB_OUTPUT`.
 *   entity-schema-package.ts verify   Fails unless the generated folder matches `$PACKAGE_VERSION`.
 *
 * The output is underscored rather than hyphenated on purpose: a `-` in a workflow expression is the
 * subtraction operator, so `steps.<id>.outputs.already-published` does not resolve.
 */

import { appendFileSync, existsSync, readFileSync, statSync } from 'node:fs';
import path from 'node:path';

export const PACKAGE_NAME = '@shopwell-ag/entity-schema-types';
export const REGISTRY_URL = 'https://registry.npmjs.org';

/**
 * Published from the repository root of the platform repository; the generator writes the folder
 * next to its own script, `scripts/entitySchemaConverter/../../entity-schema-types`.
 */
export const PACKAGE_DIRECTORY = 'src/Administration/Resources/app/administration/entity-schema-types';

export const DEFINITION_FILE = 'entity-schema-definition.d.ts';
export const LEGAL_FILES = ['LICENSE', 'NOTICE'];
export const MANIFEST_FILE = 'package.json';

/** Every file that has to exist in the folder for the published tarball to be complete. */
export const REQUIRED_FILES = [MANIFEST_FILE, DEFINITION_FILE, ...LEGAL_FILES];

/**
 * Recorded in the generated manifest. npm trusted publishing derives provenance from the workflow
 * that publishes, and refuses the upload (`E422`) when this does not name that repository.
 */
export const REPOSITORY_URL = 'git+https://github.com/shopwell-shop/shopwell.git';

/**
 * `v6.7.15.0` → `7.15.0`, keeping a release-candidate suffix (`v6.5.0.0-rc2` → `5.0.0-rc2`).
 *
 * Deliberately not the generator's `replace('v6.', '')`: that rewrites nothing for a tag it does
 * not match, so a mistyped or non-release ref publishes the ref name as the version instead of
 * failing here.
 */
const RELEASE_TAG_PATTERN = /^v6\.(\d+\.\d+\.\d+(?:-[0-9A-Za-z.]+)*)$/;

export const entitySchemaPackageVersion = (releaseTag: string): string => {
    const match = RELEASE_TAG_PATTERN.exec(releaseTag.trim());

    if (match === null) {
        throw new Error(
            `"${releaseTag}" is not a release tag of the form v6.<minor>.<patch>.<build>; refusing to derive an npm version from it.`,
        );
    }

    return match[1];
};

/**
 * Problems that make the generated manifest unpublishable, as messages rather than a boolean so a
 * failure says which field is wrong. Takes the parsed manifest, so the checks stay testable without
 * a filesystem.
 */
export const manifestProblems = (manifest: Record<string, unknown>, version: string): string[] => {
    const problems: string[] = [];

    if (manifest.name !== PACKAGE_NAME) {
        problems.push(`name is ${JSON.stringify(manifest.name)}, expected ${JSON.stringify(PACKAGE_NAME)}`);
    }

    if (manifest.version !== version) {
        problems.push(`version is ${JSON.stringify(manifest.version)}, expected ${JSON.stringify(version)}`);
    }

    if (manifest.license !== 'Apache-2.0') {
        problems.push(`license is ${JSON.stringify(manifest.license)}, expected "Apache-2.0"`);
    }

    if (manifest.types !== DEFINITION_FILE) {
        problems.push(`types is ${JSON.stringify(manifest.types)}, expected ${JSON.stringify(DEFINITION_FILE)}`);
    }

    const repository = manifest.repository as { url?: unknown } | undefined;

    if (repository?.url !== REPOSITORY_URL) {
        problems.push(`repository.url is ${JSON.stringify(repository?.url)}, expected ${JSON.stringify(REPOSITORY_URL)}`);
    }

    // A scoped package defaults to restricted access, which npm refuses without a paid plan — and
    // the failure would surface at publish time rather than here.
    const publishConfig = manifest.publishConfig as { access?: unknown } | undefined;

    if (publishConfig?.access !== 'public') {
        problems.push(`publishConfig.access is ${JSON.stringify(publishConfig?.access)}, expected "public"`);
    }

    const files = manifest.files;

    if (!Array.isArray(files)) {
        problems.push(`files is ${JSON.stringify(files)}, expected an array whitelisting the definition and legal files`);
    } else {
        for (const required of [DEFINITION_FILE, ...LEGAL_FILES]) {
            if (!files.includes(required)) {
                problems.push(`files does not whitelist ${JSON.stringify(required)}`);
            }
        }
    }

    return problems;
};

/** Problems that make a generated file unpublishable — empty, or only the empty-schema stub. */
export const definitionProblems = (definition: string): string[] =>
    definition.trim() === '' ? [`${DEFINITION_FILE} is empty`] : [];

/**
 * The tag the release is for. GitHub Actions exposes it as `GITHUB_REF_NAME`; `CI_COMMIT_TAG` is the
 * name the upstream generator reads and is honoured first so a local or GitLab run behaves the same.
 */
export const releaseTagFromEnvironment = (environment: NodeJS.ProcessEnv = process.env): string => {
    const tag = (environment.CI_COMMIT_TAG ?? environment.GITHUB_REF_NAME ?? '').trim();

    if (tag === '') {
        throw new Error('Neither CI_COMMIT_TAG nor GITHUB_REF_NAME is set; cannot tell which release is being published');
    }

    return tag;
};

const fetchPublishedVersions = async (): Promise<Record<string, unknown>> => {
    const url = `${REGISTRY_URL}/${PACKAGE_NAME.replace('/', '%2f')}`;
    let lastError: unknown;

    for (let attempt = 1; attempt <= 3; attempt += 1) {
        try {
            const response = await fetch(url, { headers: { accept: 'application/json' } });

            // A package that was never published is not an error — it is the first release.
            if (response.status === 404) {
                return {};
            }

            if (!response.ok) {
                throw new Error(`${PACKAGE_NAME}: registry returned HTTP ${response.status}`);
            }

            const metadata = (await response.json()) as { versions?: Record<string, unknown> };

            return metadata.versions ?? {};
        } catch (error) {
            lastError = error;

            if (attempt < 3) {
                await new Promise((resolve) => setTimeout(resolve, attempt * 1000));
            }
        }
    }

    throw lastError;
};

const writeOutput = (name: string, value: string): void => {
    const output = process.env.GITHUB_OUTPUT;

    if (output === undefined) {
        // A missing output file means nothing downstream can read the value. In CI that is a broken
        // job, not a no-op, so it fails there and only prints for a local run.
        if (process.env.CI === 'true') {
            throw new Error('GITHUB_OUTPUT is required in CI');
        }

        console.log(`${name}=${value}`);

        return;
    }

    appendFileSync(output, `${name}=${value}\n`, 'utf8');
};

const derive = async (): Promise<void> => {
    const version = entitySchemaPackageVersion(releaseTagFromEnvironment());
    const alreadyPublished = Object.hasOwn(await fetchPublishedVersions(), version);

    console.log(`${PACKAGE_NAME}@${version} is ${alreadyPublished ? 'already published' : 'not published yet'}`);

    writeOutput('version', version);
    writeOutput('already_published', alreadyPublished ? 'true' : 'false');
};

const verify = (): void => {
    const version = (process.env.PACKAGE_VERSION ?? '').trim();

    if (version === '') {
        throw new Error('PACKAGE_VERSION is required');
    }

    const directory = path.join(process.env.GITHUB_WORKSPACE ?? process.cwd(), PACKAGE_DIRECTORY);

    if (!existsSync(directory)) {
        throw new Error(`${PACKAGE_DIRECTORY} does not exist; the generator did not write a package`);
    }

    const problems: string[] = [];

    for (const required of REQUIRED_FILES) {
        const file = path.join(directory, required);

        if (!existsSync(file)) {
            problems.push(`${required} is missing`);
        } else if (statSync(file).size === 0) {
            problems.push(`${required} is empty`);
        }
    }

    if (problems.length === 0) {
        problems.push(
            ...manifestProblems(
                JSON.parse(readFileSync(path.join(directory, MANIFEST_FILE), 'utf8')) as Record<string, unknown>,
                version,
            ),
            ...definitionProblems(readFileSync(path.join(directory, DEFINITION_FILE), 'utf8')),
        );
    }

    if (problems.length > 0) {
        throw new Error(`${PACKAGE_NAME}@${version} is not publishable:\n  - ${problems.join('\n  - ')}`);
    }

    console.log(`${PACKAGE_NAME}@${version} contains ${REQUIRED_FILES.join(', ')} and is ready to publish`);
};

const main = async (): Promise<void> => {
    const [command = ''] = process.argv.slice(2);

    if (command === 'derive') {
        await derive();

        return;
    }

    if (command === 'verify') {
        verify();

        return;
    }

    throw new Error(`Usage: ${path.basename(process.argv[1] ?? 'entity-schema-package.ts')} <derive|verify>`);
};

if (import.meta.url === `file://${process.argv[1]}`) {
    await main();
}
